#![feature(fs_set_times)]
use std::fs::{self, FileTimes};
use std::time::SystemTime;

fn main() -> std::io::Result<()> {
    let now = SystemTime::now();
    let times = FileTimes::new()
        .set_accessed(now)
        .set_modified(now);
    fs::set_times("foo.txt", times)?;
    Ok(())
}
